/**
 * Magical String
 * Intuition: The string 1221121… is generated by the run-length encoding of itself: after the seed 1,2,2, the count at `readPointer` says how many copies of the alternating digit 1/2 to append. Count 1s while building only n characters.
 * Approach: 1. n=0 → 0; n≤3 → 1 (the seed has a single 1). 2. Array [1,2,2], `onesCount=1`, `readPointer=2`, `digitToCreate=1`. 3. While length < n, append `generatedSequence[readPointer]` copies of `digitToCreate` (only while length < n), increment ones when appending 1, then flip the digit and advance the reader. 4. Return `onesCount`.
 * Dry Run: n = 6.
 *   - Seed [1,2,2], ones=1. readPointer=2 says two 1s → [1,2,2,1,1], ones=3. Flip to 2, pointer=3 says one 2 → [1,2,2,1,1,2]. Length 6, ones=3.
 * Time Complexity: O(n)
 * Space Complexity: O(n)
 */
var magicalString = function (n) {
  if (n === 0) {
    return 0;
  }
  if (n <= 3) {
    return 1;
  }

  const generatedSequence = [1, 2, 2];
  let onesCount = 1;

  let readPointer = 2;
  let digitToCreate = 1;

  while (generatedSequence.length < n) {
    let repeatCount = generatedSequence[readPointer];

    let currentAppendCount = 0;
    while (currentAppendCount < repeatCount) {
      if (generatedSequence.length < n) {
        generatedSequence.push(digitToCreate);
        if (digitToCreate === 1) {
          onesCount++;
        }
      }
      currentAppendCount++;
    }

    readPointer++;
    digitToCreate = digitToCreate === 1 ? 2 : 1;
  }

  return onesCount;
};
